"""Remove fixed geometry choices from newly copied constructor helpers.

Dynamic switches, unlinked chosen values, animation and stateful graphs stay
intact. This changes no public socket, formula, geometry test or tolerance.
Call on a private copy or a newly constructed helper, never a loaded user tree.
"""

OPAQUE = frozenset(('GeometryNodeSimulationInput', 'GeometryNodeSimulationOutput',
    'GeometryNodeBake', 'GeometryNodeViewer', 'GeometryNodeForeachGeometryElementInput',
    'GeometryNodeForeachGeometryElementOutput'))


def simplify(tree):
    if tree.animation_data or any(node.mute or node.bl_idname in OPAQUE for node in tree.nodes):
        return dict(folded=[], removed=[], opaque=True)
    if any(link.is_muted or not link.is_valid for link in tree.links):
        return dict(folded=[], removed=[], opaque=True)
    before=len(tree.nodes); folded=[]
    for node in list(tree.nodes):
        if node.bl_idname!='GeometryNodeSwitch' or node.input_type!='GEOMETRY': continue
        condition=node.inputs['Switch']
        if condition.is_linked: continue
        chosen=node.inputs['True' if condition.default_value else 'False']
        if len(chosen.links)!=1: continue
        source=chosen.links[0].from_socket
        # Keep distinct incoming paths distinct even when the chosen socket is
        # already linked directly to the same multi-input destination. Blender
        # may coalesce an identical link. A reroute preserves multiplicity.
        passthrough=tree.nodes.new('NodeReroute')
        passthrough.label='Fixed geometry choice / '+node.name
        tree.links.new(source,passthrough.inputs[0])
        for link in list(node.outputs['Output'].links):
            target=link.to_socket
            if target.is_multi_input:
                # Keep exact Join Geometry ordering, including repeated links.
                replacement=tree.links.new(passthrough.outputs[0],target)
                replacement.swap_multi_input_sort_id(link)
                tree.links.remove(link)
            else:
                tree.links.new(passthrough.outputs[0],target)
        folded.append(node.name)
        tree.nodes.remove(node)
    if not folded: return dict(folded=[], removed=[], opaque=False)

    incoming={node:[] for node in tree.nodes}; pairs={}
    for link in tree.links: incoming[link.to_node].append(link.from_node)
    for node in tree.nodes:
        paired=getattr(node,'paired_output',None)
        if paired is not None: pairs[node]=paired; pairs[paired]=node
    live={node for node in tree.nodes if node.type in ('GROUP_INPUT','GROUP_OUTPUT') or node.bl_idname=='NodeFrame'}
    pending=[node for node in tree.nodes if node.type=='GROUP_OUTPUT']; visited=set()
    while pending:
        node=pending.pop()
        if node in visited: continue
        visited.add(node); live.add(node); pending.extend(incoming[node])
        if node in pairs: pending.append(pairs[node])
    removed=[node.name for node in tree.nodes if node not in live]
    for node in list(tree.nodes):
        if node not in live: tree.nodes.remove(node)
    return dict(folded=folded, removed=removed, opaque=False,
                original_nodes=before, retained_nodes=len(tree.nodes))
